  "Amount of particles released on upgrade now is dependent on which variant of action mode you choose":"升级时释放的粒子数量现在取决于你选择的操作模式变体",
  "An error occured while reading the file":"读取文件时出错",
  "An exponent! Finally!":"终于有个指数了！",
  "An extension to Cells. You may have noticed that an Extremecap has been in place at 2^1024 (1.798e308) Cells, which nerfs your gain significantly. Well, the Bacteria layer is here to provide you with extreme boosts to overcome this cap and beyond! On reset, it resets the Cells layer and any prior layers, wipes out your EC and halves your EF. Replication base is now 5mins and power is x1.5 (no softcap yay! but there is a hardcap at x5 best bacteria gained on reset) Instead of traditional upgrades, it works as a Skill Tree system, where one can buy upgrades using Skill Points (SP) (gained by spending Bacteria/PF) and can respec the upgrades to get all your SP back. This mechanic is why it makes this layer the most strategic layer by far.":"这是细胞的扩展。你可能已经注意到，细胞在 2^1024（1.798e308）处一直存在一个「极限上限」，会大幅削弱你的获取。现在，细菌层来了，它提供极端增益，帮你突破这个上限、走得更远！重置时，它会重置细胞层及此前所有层，清空你的 EC 并把 EF 减半。复制基础改为 5 分钟，威力为 ×1.5（没有软上限，耶！但重置时获得的细菌最好值硬上限于 ×5）。它不使用传统升级，而是技能树系统：用技能点（SP，通过消耗细菌 / 点数碎片获得）购买升级，并可洗点取回全部 SP。正是这套机制让它成为本作策略性最强的一层。",
