  "CONGRATS! You finished Minigame Part 5! Unlock Minigame Points (replaces pdx) and the next row of achievements... Also a ^e20K button and x2 SP":"恭喜！你完成了小游戏第 5 部分！解锁小游戏点数（取代 pdx）以及下一行成就……另外还有 ^e20K 按钮与至尊点数 ×2",
