  "Congrats! You have reached Absolute True endgame at least once. This will be the best endgame tier! (Reward: x1.1 Era Fragments before nerf, and this achievement)":"恭喜！你至少一次达到绝对真实终局。这将是最好的终局档位！（奖励：削弱前纪元碎片 ×1.1，以及本成就）",
  "Congrats! You have reached endgame at least once. (Reward: x1.04 Era Crystals, x1.02 Mastery Points)":"恭喜！你至少一次达到终局。（奖励：纪元晶体 ×1.04，精通点数 ×1.02）",
  "Congrats! You have reached endgame at least once. (Reward: x1.2 Water and SP, x1.02 Era Crystals)":"恭喜！你至少一次达到终局。（奖励：水与至尊点数 ×1.2，纪元晶体 ×1.02）",
  "Congrats! You have reached high endgame at least once. (Reward: x1.04 Era Crystals, x1.03 Mastery Points)":"恭喜！你至少一次达到高终局。（奖励：纪元晶体 ×1.04，精通点数 ×1.03）",
  "Congrats! You have reached High Endgame at least once. (Reward: x1.07 Era Crystals, x1.06 Mastery Points, x1.01 Cell Base Multiplier)":"恭喜！你至少一次达到高终局。（奖励：纪元晶体 ×1.07，精通点数 ×1.06，细胞基础倍率 ×1.01）",
  "Congrats! You have reached Insanity True endgame at least once. This will be the best endgame tier! (Reward: x1.1 Era Crystals, x1.07 Mastery Points, x1.04 Cell Base Multiplier)":"恭喜！你至少一次达到疯狂真实终局。这将是最好的终局档位！（奖励：纪元晶体 ×1.1，精通点数 ×1.07，细胞基础倍率 ×1.04）",
  "Congrats! You have reached low endgame at least once. (Reward: x1.02 Era Crystals)":"恭喜！你至少一次达到低终局。（奖励：纪元晶体 ×1.02）",
  "Congrats! You have reached True endgame at least once. This was the best endgame tier (Reward: x1.1 Era Crystals, x1.07 Mastery Points, x1.04 Cell Base Multiplier, x1.02 Era Fragments [AFTER NERF])":"恭喜！你至少一次达到真实终局。这是最高的终局档位（奖励：纪元晶体 ×1.1，精通点数 ×1.07，细胞基础倍率 ×1.04，纪元碎片 ×1.02 [削弱后]）",
  "Congrats! You reached the endgame. Though, there are still SPs that you can get. Can you get the 12th, or the 13th SP?":"恭喜！你到达了终局。不过，还有 SP 可以拿。你能拿到第 12 个、甚至第 13 个 SP 吗？",
