  "Eclipse":"蚀",
  "EF is Era Fragments. Remember Point Fragments, well this has gotten so inflated that the formula is slog of the currencies (basically taking the amount of 'e's in the currency. With more EF, comes more difficulty to obtain EF, due to the nerf of /3 for x2 EF (nerf can be decreased). However, some sacred upgrades can bypass the EF nerf, but others have to endure it. Also, there are EF milestones. Also, EF Buyables, which are necessary to increase total EF, used for EF Milestones. Let's just say, EF is OP.":"EF 是纪元碎片。还记得点数碎片吗？嗯，它已经膨胀到公式取货币的 slog（基本上就是数货币里有几个 e）。EF 越多，获取 EF 反而越难，因为 ×2 EF 会被 /3 削弱（削弱可以减轻）。不过，有些神圣升级可以绕过 EF 削弱，另一些则必须承受。此外还有 EF 里程碑。还有 EF 可购买项，用来提高累计 EF，供 EF 里程碑使用。这么说吧，EF 太强了。",
  "EF Milestone 1 - Req 1,750 total EF":"EF 里程碑 1 - 需要累计 1,750 EF",
