  "Explore many unique upgrades, and get the biggest numbers possible! In this game, you will go through many different layers, unlock new and unique features like upgrades, milestones and buyables. Please visit this layer often.":"探索众多独特升级，冲击尽可能大的数字！在本游戏中，你会经历许多不同的层，解锁升级、里程碑、可购买项等新奇特性。请常回来看看这一层。",
  "Explore many unique upgrades, and get the biggest numbers possible! In this game, you will go through many different layers, unlock new and unique features like upgrades, milestones and buyables. Please visit this layer often. Also, time to complete each section: Pre-Sac: 3-4hrs, Sac to Era: 4-6hrs, Era 1 and 2: 3-5hrs, Era 3: 4-7hrs":"探索众多独特升级，冲击尽可能大的数字！在本游戏中，你会经历许多不同的层，解锁升级、里程碑、可购买项等新奇特性。请常回来看看这一层。另外，各阶段通关时间：献祭前 3-4 小时，献祭到纪元 4-6 小时，纪元 1 与 2 3-5 小时，纪元 3 4-7 小时",
