  "Finally, no more scrolling 30 rows":"终于不用再翻 30 行了",
  "Finally! A new layer! Mechanic: Replicate: Multiply cells by 2 at first, upgrades to increase that. At first, replicate time is 20 seconds, upgrades and buyables to decrease that as well. At 1,000 cells there is a softcap, the multiplier decreases as cells increase after 1,000. Strategy of whether to buy buyable/save up/buy upgrade is crucial for progression. Upgrades and buyables can delay the softcap, reduce the softcap strength, increase cell gain on replicate and reduce cell replication time":"终于！一个新层！机制：复制：一开始把细胞 ×2，升级可以提高该倍率。一开始复制时间是 20 秒，升级和可购买项可以降低它。达到 1,000 细胞后出现软上限，超过 1,000 后倍率随细胞增加而下降。买可购买项 / 攒着 / 买升级之间的策略对推进至关重要。升级与可购买项可以延后软上限、削弱软上限强度、提高复制时的细胞获取、缩短复制时间",
  "Find out a way to get BM4.":"找到获得 BM4 的方法。",
