  "First Bacteria Reset":"第一次细菌重置",
  "First Cell Boost before the next layer (When you unlock this milestones section)":"下一层之前的第一个细胞增益（解锁该里程碑区域时）",
  "First Completion: Unlock new Mastery Upgrades, a BIG exponent to PF gain.":"首次完成：解锁新的精通升级，点数碎片获取获得巨量指数。",
  "Firstly, let's talk about softcaps. There are many softcaps after e1T effect, ranging from e1T to e15T and some at ee15. You will see some caps.":"先说说软上限。e1T 效果之后有很多软上限，从 e1T 到 e15T，还有一些在 ee15。你会遇到一些上限。",
