  "In an instant, rain poured down the land, and further exacerbated the seriousness of the situation. The amount of water increases based on itself.":"一瞬间，暴雨倾盆而下，进一步加剧了局势的严峻。水量根据自身增加。",
  "In every layer, there may or may not be one (or two) letters to identify the layer. This is given in the layer infobox. U stands for Upgrades, M stands for Milestones, B stands for buyables. In a milestone, the naming is just [Layer]M[MS#]. However, things get complicated in upgrades. First upgrades may say the upgrade number, while later upgrades will say [Layer]U[Row][Column]. Same goes with achievements. (Ach [Row][Column])":"在每个层里，可能会有一到两个字母用于标识该层。这写在层的信息框里。U 代表升级，M 代表里程碑，B 代表可购买项。里程碑的命名就是 [层]M[里程碑编号]。不过升级就复杂了。早期的升级会直接写升级编号，后期的升级会写 [层]U[行][列]。成就同理。（成就 [行][列]）",
  "In here, you can get numbers up to e1,500! For now, choose whether you want to buy the upgrade. Prestige effect softcaps at xe6,500 and supercaps at xe1M.":"在这里，你可以把数字做到 e1,500！眼下先决定要不要买这项升级。威望效果在 ×e6,500 软上限、在 ×e1M 超上限。",
  "In layer effect/upg effect, shows (Softcapped) / (Supercapped) when reaching softcap or supercap":"在层效果 / 升级效果中，达到软上限或超上限时会显示（软上限）/（超上限）",
  "In Mastery Challenge, DO NOT RESET FOR PRESTIGE IF YOU DID NOT GET THE FIRST BASIC MILESTONE. Get it by buying all upgs in Basic, Rebirth, then buy more upgrades, then rebirth, then buy last row of basic, then you can get milestone.":"在精通挑战中，如果你还没拿到第一个基础里程碑，千万不要为了威望而重置。拿法：先把基础层、重生层的升级全部买完，再多买一些升级，然后重生，再买基础层最后一行，之后你就能拿到该里程碑了。",
  "In mastery challenges, reduce EC and Mastery Points nerf from ^0.1 to ^0.12":"在精通挑战中，把 EC 与精通点数的削弱从 ^0.1 放宽到 ^0.12",
  "In mastery challenges, reduce EC and Mastery Points nerf from ^0.12 to ^0.14":"在精通挑战中，把 EC 与精通点数的削弱从 ^0.12 放宽到 ^0.14",
