  "Reduce scaling of EF from 2.9 to 2.85. Also, at 27 Era Buyable 9s, gain a xee18 MP boost and an x5e15 EC boost.":"EF 成长从 2.9 降到 2.85。另外，在 27 个纪元可购买项 9 时，获得超级点数 ×ee18 与 EC ×5e15 的增益。",
