  "Remarkable":"非凡",
  "Remember Hardening I and II? Hardening III Gives: SB1 and SB6 is stronger":"还记得硬化 I 和 II 吗？硬化 III 提供：SB1 与 SB6 更强",
  "Remember the MEGA LAYER? It is OP, alright. But, this requires e82,500 Mega Points to unlock. That's how OP it is! And, sacrifice milestones will not come every 1 sac.":"还记得超级层吗？它确实很强。但它需要 e82,500 超级点数才能解锁。就是这么强！而且献祭里程碑不会每 1 次献祭就来一个。",
  "Remember to drink water :) and rest your eyes":"记得喝水 :) 让眼睛休息",
  "Remember to join my discord server! Reminder 2 to drink water :) and rest your eyes. (Fun fact, you could have watched Jurrasic Park 11.3 times...)":"记得加入我的 Discord 服务器！提醒 2：喝水 :) 让眼睛休息。（冷知识：你本可以看 11.3 遍《侏罗纪公园》……）",
  "Reminder 3 to drink water, rest your eyes, eat and sleep, take a walk. Fun fact 3: Assuming you read at an average pace of 0.5 pages/minute, you would have read about 5,040 pages by now if you did not sleep... That's probably more than you've ever read. Anyway, here's a x20 Rebirth Point boost if you are still there... and an x3 Prestige Point boost":"提醒 3：喝水、让眼睛休息、吃饭睡觉、出去走走。冷知识 3：假设你以每分钟 0.5 页的平均速度阅读，如果你一直不睡，到现在大约读了 5,040 页……大概比你这辈子读过的都多。总之，如果你还在，送你重生点数 ×20……以及威望点数 ×3",
  "Removed 'Please do not complain' notes in era layer":"移除了纪元层里“请不要抱怨”的备注",
