  "Removed playtime milestones FOR GOOD!":"永久移除游玩时长里程碑！",
  "Renamed all Upgrades":"重命名了所有升级",
  "Renamed savebanks from 'Sac Stage 3' to 'Supreme Stage 5'":"存档库名称从“献祭阶段 3”改为“至尊阶段 5”",
