  "Rep Upgrades [Exclusive Rarity]":"换重生升级 [专属稀有度]",
  "Req: 4e9 PF, without any best RP. (Reward: x1.25 RP)":"要求：4e9 点数碎片，且没有任何最佳重生点数。（奖励：重生点数 ×1.25）",
  "Req: 5e8 PF, without any best RP. (Reward: x1.1 RP)":"要求：5e8 点数碎片，且没有任何最佳重生点数。（奖励：重生点数 ×1.1）",
  "Req: Before Getting Pres Upg 55, get e388.1M PF. (Reward: x1.05 SP)":"要求：在获得威望升级 55 之前，获得 e388.1M 点数碎片。（奖励：至尊点数 ×1.05）",
  "Req: e78K PF, with less than 2 Sacrifice. (Reward: x1.2 MP)":"要求：e78K 点数碎片，且献祭次数少于 2。（奖励：超级点数 ×1.2）",
  "Req: Get e152,980,000 PF, without any supreme (Reward: x1.04 SP)":"要求：在没有任何至尊的情况下获得 e152,980,000 点数碎片（奖励：至尊点数 ×1.04）",
  "Req: In Sac Challenge 3, without completing it before, get e191,450 PF. (Reward: x1.1 Energy)":"要求：在献祭挑战 3 中（此前未完成过），获得 e191,450 点数碎片。（奖励：能量 ×1.1）",
