  "Rolling cooldown is decreased from 5 to 2 seconds. Luck Buyable 1's effect is slightly stronger.":"抽取冷却从 5 秒降到 2 秒。幸运可购买项 1 的效果略微增强。",
  "Rolling cooldown is halfed, and RNG Points is doubled.":"抽取冷却减半，RNG 点数翻倍。",
  "Row 1 is the 'Funny Number' row.":"第 1 行是“有趣数字”行。",
  "Row 1: In the options. <br> Row 2 and the first 2 achievements of Row 3: Stalling before certain upgrade/milestone/reset layer. [IF YOU MISS THEM, YOU CAN GET THEM BY CURRENT ENDGAME]<br> The last four achievements in Row 3 is endgame achievements, which require quite alot of PF...<br> Row 4 Achievements are unlocked after Era 3, with the v4.0 update. There are 6 achievements in this row, with the last 3 relying on the RNG Minigame. Ach 43 [intended way] is to stall after a huge challenge but also can be gotten ANYTIME in Era 4/post MC3 (enter Mastery Challenge, exit, buy all ups (dont get era), get Ach). Also, Overload means 'staying in a mastery challenge longer than intended/going back to a mastery challenge long after you have already beaten it'":"第 1 行：在设置里。<br> 第 2 行与第 3 行的前 2 个成就：在特定升级 / 里程碑 / 重置层之前停滞。[如果你错过了，可以靠当前终局拿到]<br> 第 3 行的最后 4 个成就是终局成就，需要相当多的点数碎片……<br> 第 4 行成就在纪元 3 之后随 v4.0 更新解锁。这一行共 6 个成就，后 3 个依赖 RNG 小游戏。成就 43［预设玩法］是在一场大挑战之后停滞，但在纪元 4 / MC3 之后随时都能拿到（进入精通挑战、退出、买完所有升级（不要拿纪元）、拿到成就）。另外，Overload 指的是“在精通挑战里待得比预期更久 / 在你早已通关之后又回到精通挑战”",
  "Row 2 is the start of the Big Numbers":"第 2 行是大数字的开端",
