  "Sacrifice Cost Scaling is now increased from 3.6 to 7.5 exponent. [Super Nerf: At e100B PF, PF gain ^0.1 and sacrifice exponent is permanently at 100.] ":"献祭花费成长从 3.6 指数提升到 7.5。[超级削弱：在 e100B 点数碎片时，点数碎片获取 ^0.1，且献祭指数永久固定为 100。]",
  "Sacrifice formulae is weaker":"献祭公式被削弱",
  "Sacrifice is the first static layer, which means that the price will change based on how many sacrifices you have. Anyways, this is the MOST OP Layer, and it is used to provide insane boosts. There will be new features on this.":"献祭是第一个静态层，也就是说价格会随你拥有的献祭次数变化。总之，这是最强的一层，用于提供疯狂增益。这里还会有新特性。",
  "Sacrifice Layer [Sac]":"献祭层 [Sac]",
  "Sacrifice now RESETS energy and Energy upgrades (some sacs can keep certain rows of energy upgrades)":"献祭现在会重置能量与能量升级（部分献祭可保留特定的能量升级行）",
