  "The endgame of stage 1 layers. Resets all layers when going into challenge, even future ones! Buy all previous column's upgrades to unlock a new column. Stacks up to 5. Unlock new rows by completing mastery challenge.":"第一阶段各层的终局。进入挑战时会重置所有层，甚至包括未来的层！买完上一列的全部升级即可解锁新一列。最多叠到 5。完成精通挑战可解锁新行。",
  "The Era Layer [NO SHORT FORM]":"纪元层 [无简称]",
  "The Fifth RNG Milestone (Requires Best RarityID: 32)":"第五个 RNG 里程碑（需要最佳稀有度 ID：32）",
  "The Fifth Sacrifice":"第五次献祭",
  "The final Basic Upgrade S. Reward: ^1.00025 PF.":"最后一项基础升级 S。奖励：点数碎片 ^1.00025。",
  "The final push...! Increase of power in MC3 is stronger. (Largest timewall in game)":"最后的冲刺……！MC3 中幂的提升更强。（本作最大的时间墙）",
  "The FINAL RNG Milestone (Requires Best RarityID: 238,360)":"最后一个 RNG 里程碑（需要最佳稀有度 ID：238,360）",
  "The final upgrade before the next reset layer: X5 POINT FRAGMENTS!!":"下一重置层之前的最后一项升级：点数碎片 ×5！！",
  "The first boost":"第一个增益",
  "The first layer of the game, requires 10 Point Fragments. The start to big numbers.":"游戏的第一层，需要 10 点数碎片。通往大数字的起点。",
  "The first real trade-off since when? Well, just think about it.":"自打什么时候起第一个真正的取舍？嗯，自己想想吧。",
