  "The Last Upgrade, before the next Reset Layer":"下一个重置层之前的最后一项升级",
  "The layer *= button is now 1.5 times stronger. Every 0.05 seconds, passively generates the Layer *= button (click, not hold part) [doesn't work if layer>e308], with 1/20 of the effect. Hold mult is increased to 2.5.":"层级 *= 按钮现在强 1.5 倍。每 0.05 秒被动生成一次层级 *= 按钮（点击部分，不含长按）[层级大于 e308 时不生效]，效果为 1/20。长按倍率提升到 2.5。",
  "The layer *= button is now 2 times stronger. Passive button has 4x the effect. Hold mult is increased to 3.":"层级 *= 按钮现在强 2 倍。被动按钮效果 ×4。长按倍率提升到 3。",
  "The layer *= button is now 40% stronger. Hold mult is increased to 6!":"层级 *= 按钮现在强 40%。长按倍率提升到 6！",
  "The Least Button Presses Series continues, and is the finale of the Strategic Manipulation series.":"“最少按键”系列继续，这也是策略操作系列的终章。",
  "The Mag *= 1.0001 button does not cost ANY MiP, and the effect is x7. Unlock some Minigame Milestones. (You have to get Era 1 to unlock them)":"Mag *= 1.0001 按钮不消耗任何 MiP，且效果为 ×7。解锁一些小游戏里程碑。（需要先达到纪元 1 才能解锁）",
  "The main part of the update is the huge extension for the Minigame. 20 new MINIGAME ????s, 1 new currency, 12 new achievements, 2 new features, up to the Fs and more!":"本次更新的主体是小游戏的大幅扩展。20 个新的 MINIGAME ？？？？、1 种新货币、12 个新成就、2 项新特性，一直到 F 级以及更多！",
  "The Master that you, yourself are":"你自己就是那位大师",
  "The Mastery Layer [NO SHORT FORM]":"精通层 [无简称]",
  "The Modding Tree Discord":"The Modding Tree Discord 服务器",
  "The most insane boost. xe5M PF. Yes. E5M. You heard that right.":"最疯狂的增益。点数碎片 ×e5M。对，E5M。你没看错。",
  "The New Reset Layer":"新的重置层",
  "The Ninth RNG Milestone (Requires Best RarityID: 225)":"第九个 RNG 里程碑（需要最佳稀有度 ID：225）",
  "The Power Milestone (5e2,463 Energy)":"力量里程碑（5e2,463 能量）",
  "The rebirth Layer (R, or Reb)":"重生层（R 或 Reb）",
