  "The second row!":"第二行！",
  "The Second Sacrifice":"第二次献祭",
  "The Second Water Milestone (1.111e1111 Water)":"第二个水里程碑（1.111e1111 水）",
  "The secret achievement layer [achievements part] (just some hints)":"秘密成就层 [成就部分]（只是一些提示）",
  "The Seventh RNG Milestone (Requires Best RarityID: 51)":"第七个 RNG 里程碑（需要最佳稀有度 ID：51）",
  "The Sixth RNG Milestone (Requires Best RarityID: 40)":"第六个 RNG 里程碑（需要最佳稀有度 ID：40）",
  "The Start":"起点",
  "The start of a new layer":"一个新层的开始",
  "The SUPREME Layer [S]":"至尊层 [S]",
  "The Supremely OP UPG":"至尊强到离谱的升级",
  "The Tenth RNG Milestone (Requires Best RarityID: 376)":"第十个 RNG 里程碑（需要最佳稀有度 ID：376）",
  "The Third RNG Milestone (Requires Best RarityID: 10)":"第三个 RNG 里程碑（需要最佳稀有度 ID：10）",
  "The Third Sacrifice":"第三次献祭",
  "The Tree":"树",
  "The True Energy Milestone (1e5,380 Energy)":"真实能量里程碑（1e5,380 能量）",
  "The Ultima-Tradeoff":"终极取舍",
  "The unlocking of DS7":"DS7 的解锁",
  "The unlocking of the cells layer":"细胞层的解锁",
  "The Water Layer [W]":"水层 [W]",
  "The water rises at an impressive pace. You, as the leader of the pack, realise that you have to educate others to survive through the disaster. The fundementals would have to be re-learnt. xe2.1e21 BP.":"水位以惊人的速度上涨。作为队伍的领袖，你意识到必须教会其他人如何在灾难中生存。基础必须重新学起。基础点数 ×e2.1e21。",
  "Then more energy":"然后是更多能量",
  "Then what?":"然后呢？",
  "Theoretical":"理论性",
  "There are only 4 new buttons here. Buttons now decrease your Minigame Point amount alot, you may have to keep your Minigame Points at a suitable level. The mag buttons will be the star of the show, pushing you from MU12 to MM8.":"这里只有 4 个新按钮。按钮现在会大幅扣减你的小游戏点数，你可能需要把小游戏点数维持在合适水平。mag 按钮将成为主角，把你从 MU12 推到 MM8。",
  "There are only 4 new buttons here. Buttons now decrease your Minigame Point amount alot, you may have to keep your Minigame Points at a suitable level. The mag buttons will be the star of the show, pushing you from MU12 to MM8. Also, the number after 'F' shows the amount of 'e's there are in the number. Thus, F2 = ee10, F3 = eee10, F10 = eeeeeeeeee10 (am i right??)":"这里只有 4 个新按钮。按钮现在会大幅扣减你的小游戏点数，你可能需要把小游戏点数维持在合适水平。mag 按钮将成为主角，把你从 MU12 推到 MM8。另外，'F' 后面的数字表示这个数里有几个 e。因此 F2 = ee10，F3 = eee10，F10 = eeeeeeeeee10（我没说错吧？？）",
  "There will be a 2nd tree. However, this only happens in Era 3. Up to 30 rows per tree. ":"会有第 2 棵树。不过那只在纪元 3 出现。每棵树最多 30 行。",
  "theres more???":"还有更多？？？",
  "These caps nerfs the boost. There are upgrades to reduce the nerf. There are upgrades to increase the starting cap. There are currently 3 stages of caps, which is Softcap, Supercap and Hypercap.":"这些上限会削弱增益。有升级可以减轻削弱，也有升级可以提高起始上限。目前共有 3 级上限：软上限、超上限、极上限。",
  "Third Cell Boost before the next layer (3e271 Cells)":"下一层之前的第三个细胞增益（3e271 细胞）",
  "This includes xe3e19 PP, x5000 EC":"这包含威望点数 ×e3e19、EC ×5000",
  "This is a side layer. It is not needed to progress. The Minigame Layer in The Point Tree encompasses 8 rows of achievements, 30+ buttons, 6 parts, huge numbers, strategic manipulation, and MORE! Unlock new buttons from most achievements. The last achivement of rows 4-8 gives boosts. p.s. For Rows 1-3, order matters. You are not supposed to get all in order but when you can get them. Buttons from some achievements will be useful in other rows.":"这是一个支线层，对推进主线并非必需。点数树的小游戏层包含 8 行成就、30+ 按钮、6 个部分、巨大的数字、策略操作，还有更多！大部分成就会解锁新按钮。第 4-8 行的最后一个成就会给出增益。附注：第 1-3 行顺序很重要。你不该按顺序拿满，而是能拿的时候就去拿。某些成就给的按钮在其他行也会有用。",
  "This is a test popup.":"这是一条测试弹窗。",
  "This is the second side layer, unlocked from getting Era 3. It is not needed to progress. The RNG-Minigame Layer in The Point Tree has a main clickable to roll for different rarities [3x (can decrease) the rng needed to get to next rarity], which gives 2^RarityID RNG Points, which can be spent on different milestones and buyables to increase luck (multiplying RNG), decreasing roll cooldown, increasing RNG Point Mult, adding new Luck Buyables, and more. There are 150 unique rarity names, and 25 pre-names. Afterwards it would loop back and add '1' to the end,":"这是第二个支线层，达到纪元 3 后解锁。对推进主线并非必需。点数树的 RNG 小游戏层有一个主可点击项，用于抽取不同稀有度［每提升一级，所需 RNG 变为原来的 3 倍（可降低）］，抽取会给予 2^稀有度ID 的 RNG 点数；这些点数可花在各类里程碑与可购买项上，用来提高幸运（倍增 RNG）、降低抽取冷却、提高 RNG 点数倍率、解锁新的幸运可购买项等等。共有 150 个独特稀有度名与 25 个前置词。之后会循环回去并在末尾加一个「1」，",
  "This layer requires some form of strategy.":"这一层需要一点策略。",
  "This save appears to be for a different mod! Are you sure you want to import?":"这个存档似乎来自另一个模组！你确定要导入吗？",
