  "Unlock ?&!?!#$&!??":"解锁 ?&!?!#$&!??",
  "Unlock 1 new Era Buyable. Automate Era Buyable 5, it also costs no EC. Also, unlock more EF upgrades.":"解锁 1 个新纪元可购买项。自动购买纪元可购买项 5，且它不花费 EC。同时解锁更多 EF 升级。",
  "Unlock 1 new Era Buyable. Automate Era Buyable 5. Also, unlock more EF upgrades.":"解锁 1 个新纪元可购买项。自动购买纪元可购买项 5。同时解锁更多 EF 升级。",
  "Unlock 2 new Era Buyables.":"解锁 2 个新纪元可购买项。",
  "Unlock 4 new upgs":"解锁 4 项新升级",
  "Unlock a new ^e250K button. MU2 affects it at a decreasing rate while MU3 does not affect it.":"解锁一个新的 ^e250K 按钮。MU2 以递减比率影响它，MU3 不影响它。",
  "Unlock a new button. Passive generation is now 100 times stronger. (Reward: x1.05 EC) Hold Mult is 1.8.":"解锁一个新按钮。被动产出现在强 100 倍。（奖励：EC ×1.05）长按倍率为 1.8。",
  "Unlock a new currency that is used for only 1 upgrade. Some strategic manipulation, low numbers of 1e-1ex and higher numbers":"解锁一种只用于 1 项升级的新货币。需要一些策略操作，数值低到 1e-1ex 也有更高的数",
  "Unlock a new Era Fragment Milestone. Every single Sacrifice Milestone increases Everything Power by 0.0001":"解锁一个新的纪元碎片里程碑。每一个献祭里程碑都使万物威力提高 0.0001",
  "Unlock a NEW LAYER!":"解锁一个新层！",
  "Unlock a NEW LAYER! Era Buyable 4 costs nothing.":"解锁一个新层！纪元可购买项 4 不花费任何东西。",
  "Unlock a new Luck Buyable. [INFLATION!!!] Luck Buyable 1 costs nothing.":"解锁一个新的幸运可购买项。[通胀！！！] 幸运可购买项 1 不花费任何东西。",
  "Unlock a new Luck Buyable. [INFLATION!!!]. ps all buyables' effect is softcapped at 1,000 buys and hardcapped at 2,000 buys. Luck Buyable 3 costs nothing.":"解锁一个新的幸运可购买项。[通胀！！！]。ps 所有可购买项的效果在 1,000 次购买时软上限、2,000 次时硬上限。幸运可购买项 3 不花费任何东西。",
  "Unlock a new Luck Buyable. Rarity scaling is decreased (from x3 per rarity to x2.9 per rarity)":"解锁一个新的幸运可购买项。稀有度成长降低（每级 ×3 → ×2.9）",
  "Unlock a new Sacrifice Feature, and unlock a new Era Feature.":"解锁一项新献祭特性，并解锁一项新纪元特性。",
  "Unlock a new tab, and a new ??? [Cost: 2192 Sac and 3e14 (300T) Era Crystals":"解锁一个新标签页，以及一个新的？？？[花费：2192 次献祭与 3e14（300T）纪元晶体",
  "Unlock a row of Basic Upgrades, +^0.02 BP, Unlock 1 new RP Milestone":"解锁一行基础升级，基础点数 +^0.02，解锁 1 个新重生点数里程碑",
  "Unlock a row of Mega Upgrades, ^1.004 PF":"解锁一行超级升级，点数碎片 ^1.004",
  "Unlock a row of Rebirth Upgrades, +^0.02 RP-MP":"解锁一行重生升级，重生点数至超级点数 +^0.02",
  "Unlock a temporary Pre-nextLayer milestones tab, which provides a slew of new boosts to unlock the next layer. Also reveals the next layer.":"解锁一个临时的「下一层之前」里程碑标签页，提供大量新增益以帮助你解锁下一层。同时揭示下一层。",
  "Unlock another layer.":"解锁另一个层。",
  "Unlock Cell Buyable 3, and reduce cell softcap":"解锁细胞可购买项 3，并降低细胞软上限",
  "Unlock Challenge tab, More Mega Upgrades, x2,000 Energy. Keep Energy Milestones.":"解锁挑战标签页，更多超级升级，能量 ×2,000。保留能量里程碑。",
  "Unlock Dimensional Shift 2. ^1.006 PF, +^0.025 RP and PP, x2727 Energy. Keep BU81-84":"解锁维度转换 2。点数碎片 ^1.006，重生点数与威望点数 +^0.025，能量 ×2727。保留 BU81-84",
  "Unlock DS4. [Crazy Rarity]":"解锁 DS4。[狂暴稀有度]",
  "UNLOCK DS6, ^1.014 PF!, xe4T PF":"解锁 DS6，点数碎片 ^1.014！，点数碎片 ×e4T",
  "Unlock DS7. xe1.2558e20 PF.":"解锁 DS7。点数碎片 ×e1.2558e20。",
  "Unlock Era Buyable 2":"解锁纪元可购买项 2",
  "Unlock Era Buyable 4. This buyable's base is based on log7(Sacrifices)":"解锁纪元可购买项 4。该可购买项的基础值基于 log7(献祭次数)",
  "Unlock Era Phase 2, and Era Fragments [Omniversal Rarity]":"解锁纪元第二阶段，以及纪元碎片 [全能宇宙稀有度]",
  "Unlock Era Phase 2!":"解锁纪元第二阶段！",
  "Unlock Luck Buyable 5":"解锁幸运可购买项 5",
  "Unlock Mastery Challenge 3. Also, gain a small but significant boost of x2 EC.":"解锁精通挑战 3。另外获得一份小而关键的增益：EC ×2。",
  "Unlock Mega Buyable 1! MU9 is also stronger.":"解锁超级可购买项 1！MU9 也更强了。",
  "Unlock Mega Buyable 5":"解锁超级可购买项 5",
  "Unlock more ups woohoo! ^2 Cell Softcap start, x2 EF after nerf, ^1.01 PF, Double RNG Points.":"解锁更多升级，呜呼！细胞软上限起点 ^2，削弱后 EF ×2，点数碎片 ^1.01，RNG 点数翻倍。",
  "Unlock new Mastery Upgrades and x10,000 Mastery Points, Sac Scaling decreased to 3.5, but you cannot enter sacrifice challenges":"解锁新的精通升级并获得精通点数 ×10,000，献祭成长降到 3.5，但你不能进入献祭挑战",
  "Unlock new milestones, ^1.01 PF!":"解锁新里程碑，点数碎片 ^1.01！",
  "Unlock one more row of mega upgrades!":"再解锁一行超级升级！",
