  "Upgrade Boosting":"升级增益",
  "Upgrade Effect Softcap":"升级效果软上限",
  "Upgrade Keeping is a way for you to click less, as there is NO AUTOMATION in the game. A higher layer in the game will keep previous layer's stuff. You can also keep Milestones, Buyables and Challenges. ":"升级保留让你少点几下，因为本游戏没有自动化。更高的层会保留更低层的东西。你也可以保留里程碑、可购买项与挑战。",
  "Upgrades":"升级",
  "Upgrades are basically a broad class that only can be bought once, and gives a boost. It could be static (x), to effects, non-static, power (^), or boosts to later features":"升级基本上是一大类只能买一次并提供增益的东西。它可以是静态倍率（×）、作用于效果、非静态的幂次（^），或对后续特性的增益",
  "Upgrades that do things repeatedly. Can be a formula, or just a static boost. Also can boost multiple things at once.":"会反复生效的升级。可以是公式，也可以只是静态增益。还可以同时增益多个对象。",
