  "Welcome to rebirth. Here's a x4 point fragments for you.":"欢迎来到重生。送你一个点数碎片 ×4。",
  "Welcome to The Minigame Layer!":"欢迎来到小游戏层！",
  "Welcome to The Point Tree!":"欢迎来到点数树！",
  "Welcome to The RNG Minigame!":"欢迎来到 RNG 小游戏！",
  "Well well well... ^1.2 PF!!":"好吧好吧……点数碎片 ^1.2！！",
  "Well, after 4 months without a major update, I present to you, **the Point Tree Version 4.0** - Controlled Chaos (With Mastery Challenge 3, Dimensional Shift 7, and Era 4)":"嗯，在 4 个月没有大更新之后，我向你呈现 **点数树 4.0 版** —— 受控混沌（含精通挑战 3、维度转换 7 与纪元 4）",
  "Well, after buying this upgrade, it is just a matter of TIME before you get Era 4. Compounding III is stronger.":"嗯，买下这项升级后，拿到纪元 4 就只是时间问题了。复利 III 更强。",
  "Well, extensions... well, add new content! This adds new upgrades and/or milestones to previous layers.":"嗯，扩展……就是加新内容！为之前的层新增升级和 / 或里程碑。",
  "Well, INSANELY OP.":"嗯，强到离谱。",
  "Well, isn't it good when everything gives everything else? Yeah. For every era upgrade past 200, +0.0001 EP.":"嗯，万物互相增益的感觉不错吧？对。第 200 项之后的每项纪元升级，+0.0001 EP。",
  "Well, it's been over 700,000 Sacrifices without a Sacrifice Milestone. xee20 PF, -0.00775 Sacrifice Scaling, -0.060177 Era Scaling.":"嗯，已经超过 700,000 次献祭没有献祭里程碑了。点数碎片 ×ee20，献祭成长 -0.00775，纪元成长 -0.060177。",
  "Well, it's time. Every upgrade now reduces the power by 0.5% only instead of 1.5%. Furthermore, +^0.04 MP. [Req 0.218 RNG Power for next Up.]":"是时候了。现在每项升级只把幂降低 0.5% 而不是 1.5%。此外，超级点数 +^0.04。[下一项升级需要 0.218 RNG 幂]",
  "Well, why the new naming scheme? Simple. There can't really be much A/B/C Era Upgrades due to EFUp 10 and the buff of ErUp 1e1. (x20 EC/upg...) Some buyables, when purchased, may give free other buyables as 'effective' buyables (has the same effect as normal buyables, indicated by a '+' after the buys. Also, implemented after WG.).":"嗯，为什么要换新命名方案？很简单。由于 EFUp 10 与 ErUp 1e1 的增强，A/B/C 式的纪元升级已经没多少可排了。（每项升级 ×20 EC……）有些可购买项购买后会「免费」给予其他可购买项，称为「有效」可购买项（效果与普通可购买项相同，购买数后带一个 + 号。该机制在 WG 之后实装）。",
  "Well, you have all heard of the '+0.01 SB5 HC'...Now, it's time I reveal to you, x1.02 SB5 HC!!!":"嗯，你们都听说过「+0.01 SB5 硬上限」了……现在，让我向你们揭晓：SB5 硬上限 ×1.02！！！",
  "Well, you still enjoying The Point Tree even up to this day? Well, I am too ~Randim, Coded on 15 October 2025, 13:13GMT":"嗯，你到现在还喜欢《点数树》吗？我也是 ~Randim，写于 2025 年 10 月 15 日 13:13 GMT",
  "Welp, we've come a long way...":"唉，我们走了好长一段路……",
  "What is a BPP??":"BPP 是什么？？",
  "What is Era Crystals? It is an elusive currency for Era, and is generated. This is used to buy Tree Upgrades. These Tree Upgrades have branches connecting to them.":"纪元晶体是什么？它是纪元层的一种稀有货币，属于产出型。用于购买树升级。这些树升级之间有分支相连。",
  "What is this, exactly?":"这到底是什么？",
  "What more can I get? (Reward: x1.04 Era Fragments AFTER NERF, x1.1 Cell Softcap Delay)":"我还能拿到什么？（奖励：削弱后纪元碎片 ×1.04，细胞软上限延迟 ×1.1）",
  "What more is there?":"还有什么？",
