  "Why is there a hardcap for Supreme Buyable 5? It is just TOO OP. Hardcap varies, but starts at ^1.25.":"为什么至尊可购买项 5 有硬上限？因为它实在太强了。硬上限会变化，但起始于 ^1.25。",
  "With your Computing and Engineering Knowledge, you build many robots that help to rescue people that is down there and still trapped by the Tsunami, and even build bigger/higher platforms! ^1.0075 PF.":"凭借你的计算与工程知识，你造出许多机器人，去营救被困在下面的海啸幸存者，甚至还建起更高更大的平台！点数碎片 ^1.0075。",
