  "Woah, that Achievement, and Mastery Up. was insanely powerful... Row 12 upgrades (and the 2 other Mastery ups) is the limiter for Era 4, boost MaU153 timecap and another boost":"哇，那个成就和精通升级真是强得离谱……第 12 行升级（以及另外 2 项精通升级）是纪元 4 的门槛，增益 MaU153 的时间上限，再给一份增益",
