  "You are currently not recommended to enter this challenge.":"目前不建议你进入这个挑战。",
  "You are recommended to enter this challenge to progress.":"推荐进入此挑战以继续推进。",
  "You boost the spirits of the injured, and survived. 'Compounding' and the 12th iteration of it is stronger.":"你鼓舞了伤者的士气，并活了下来。「复利」及其第 12 次迭代更强。",
  "You can get SA32 now if you have not gotten it!":"如果你还没拿到 SA32，现在可以拿了！",
  "You can still change your dp though, by going to the console and typing 'options.dp = 10', for example.":"不过你仍然可以改 dp：打开控制台输入 'options.dp = 10' 即可，以此类推。",
  "You cannot enter any of Sac Challenges after completing Mastery Challenge 2.":"完成精通挑战 2 后你无法进入任何献祭挑战。",
  "You cannot enter any of Sac Challenges in the Mastery Challenge 2.":"在精通挑战 2 中你无法进入任何献祭挑战。",
  "You could already imagine getting to Era 4, do you? ^1.01 PF, and Era Buyable 4 is WAY stronger.":"你大概已经能想象拿到纪元 4 了吧？点数碎片 ^1.01，纪元可购买项 4 强得多。",
  "You could watch the ENTIRE Avengers Cinematic Universe 11.625 times... well... and also xe100 PF":"你本可以把漫威电影宇宙完整看 11.625 遍……嗯……另外还有点數碎片 ×e100",
  "You discovered that your algorithms could definitely boost ALOT by doing Cross-Validation. Unlock a new Power called Everything Power (EP) that ^s BP,RP,PP,MP,Energy,Water,SP,MaP,EC. +0.00675 EP.":"你发现你的算法可以通过交叉验证获得惊人提升。解锁一种新威力「万物威力」（EP），它对基础点数、重生点数、威望点数、超级点数、能量、水、至尊点数、精通点数、EC 取 ^。+0.00675 EP。",
  "You either are a cheater OR a absolute true godly no-life... Fun fact 4: If you have just left your computer on for 200 days, it will use 1200 kWh for a desktop and 360 kWh for a laptop (averages). Assuming you are in Los Angeles, you can drive a Tesla Model 3 to Beaumont, Texas for a laptop and to Montreal, Canada there, back and there again for a desktop... Oh also xe1,000,000 PF...":"你要么是作弊者，要么是真正的神级肝帝……冷知识 4：如果你只是让电脑开着 200 天，台式机大约耗 1200 度电，笔记本约 360 度（平均值）。假设你在洛杉矶，用笔记本的电量你能开特斯拉 Model 3 到德州博蒙特，用台式机的电量能到加拿大蒙特利尔再往返一次……哦对了，还有点數碎片 ×e1,000,000……",
  "You have no control. (Its up to the RNGods). ALL CURRENCIES (EXCEPT SACRIFICE) ARE NERFED TO A POWER. The power increases slowly based on RNG, and ANY UPGRADES/MILESTONES/ERAS (EXCEPT CELL UPS/MS) GOTTEN DECREASES THE EXPONENT BY 1.2%. Also, EC is always at e100. (Expect longer upgrade times for this challenge, 33min Estimated Challenge Duration). ":"你无法掌控。（一切取决于 RNG 之神）。所有货币（献祭除外）都被削弱成一个幂。该幂根据 RNG 缓慢提高，而获得的任何升级 / 里程碑 / 纪元（细胞升级与里程碑除外）都会使该指数降低 1.2%。另外，EC 恒为 e100。（本次挑战的升级时间会更长，预计耗时 33 分钟）",
  "You have the maximum amount of completions of this challenge.":"你已经达到该挑战的最大完成次数。",
  "You have unlocked all current boosts!":"你已解锁当前所有增益！",
  "You have unlocked Dimensional Shift 1. Dimensional Shifts add another column to the upgrades (Column 5). Adds another row to Basic Upgrades.":"你已解锁维度转换 1。维度转换为升级新增一列（第 5 列）。为基础升级新增一行。",
  "You have unlocked Dimensional Shift 2. Dimensional Shifts add another column to the upgrades (Column 5). Adds another row to Rebirth Upgrades.":"你已解锁维度转换 2。维度转换为升级新增一列（第 5 列）。为重生升级新增一行。",
  "You have unlocked Dimensional Shift 3. Dimensional Shifts add another column to the upgrades (Column 5). Adds another row to Prestige Upgrades.":"你已解锁维度转换 3。维度转换为升级新增一列（第 5 列）。为威望升级新增一行。",
  "You have unlocked Dimensional Shift 4. Dimensional Shifts add another column to the upgrades (Column 5). Adds another row to MEGA Upgrades.":"你已解锁维度转换 4。维度转换为升级新增一列（第 5 列）。为超级升级新增一行。",
  "You have unlocked Dimensional Shift 5. Dimensional Shifts add another column to the upgrades (Column 5). Adds another row to ENERGY Upgrades. You may control the world's power supply after this.":"你已解锁维度转换 5。维度转换为升级新增一列（第 5 列）。为能量升级新增一行。此后你可以掌控世界的电力供应。",
  "You have unlocked Dimensional Shift 6. Dimensional Shifts add another column to the upgrades (Column 5). Adds another row to SUPREME Upgrades. That's err... 11 upgrades??":"你已解锁维度转换 6。维度转换为升级新增一列（第 5 列）。为至尊升级新增一行。那是……11 项升级？？",
  "You have unlocked Dimensional Shift 7. Dimensional Shifts add another column to the upgrades (Column 5). Adds another row to Water Upgrades. Well, be lucky you got a dimension shift, I haven't forgot you!":"你已解锁维度转换 7。维度转换为升级新增一列（第 5 列）。为水升级新增一行。嗯，能拿到一次维度转换就算走运了，我没忘了你！",
  "You know the drill.":"你懂规矩的。",
  "You mean to say... That's POSSIBLE??":"你的意思是……那有可能？",
  "You multiplied your energy production by 250M!!":"你的能量产量 ×250M！！",
  "You need prestige button text":"你还没有设置威望按钮文本",
  "You Prestiged! This is the first upgrade.":"你完成了一次威望！这是第一项升级。",
  "You probably are at the Era stage if you did not venture into the minigame and played optimally. But if you are still at the beginning stage, here's a x1.5 PF for you":"如果你没去碰小游戏而是最优推进，大概已经到纪元阶段了。但如果你还停在开局阶段，送你点数碎片 ×1.5",
  "You will progress for a long time here, scrolling through upgrades, getting extensions, and occasionally unlocking new features. Most of the info of the layer is found in the Era Infobox, but Era 3+ info will be found here!":"你会在这里推进很久，翻看升级、拿扩展，偶尔解锁新特性。该层的大部分信息在纪元信息框里，但纪元 3 及以后的信息会放在这里！",
  "You're on the express route":"你在快车道上",
  "Your current progress will not be saved!":"你当前的进度不会被保存！",
  "Your first catch upgrade unlocks at Prestige Upgrade 31. Basically, it gives a HUGE boost, but with a nerf. Overall, it will be a small buff. [However, in later challenges, catch upgrades may not be worth buying due to a small static increase VS a big exponent decrease.]":"你的第一个“接住”升级在威望升级 31 解锁。基本上它给出巨大增益，但附带削弱。总体而言仍是小幅增强。[不过在后期的挑战里，由于固定小幅提升换来大幅指数下降，接住升级可能不值得买。]",
  "Yup, don't get bored.":"对，别嫌烦。",
  "Zenith":"天顶"
