  "<h3>Bacteria 10 - Fragmenting and Crystalising</h3><br>\r\n                x2 Era Fragments after nerf. Also, ^1.05 EC.<br><br>Cost: 2 SP<br><b style=\"color: ":"<h3>细菌 10 - 碎裂与结晶</h3><br>\n                削弱后的纪元碎片 ×2。另外，EC ^1.05。<br><br>花费：2 SP<br><b style=\"color: ",
  "<h3>Bacteria 11 - Fusion Upgrade</h3><br>\r\n                x1.5 EF after nerf, x25 Cell Base Mult, xe1e20 PF, /2 Replication time<br><br>Cost: 3 SP<br><b style=\"color: ":"<h3>细菌 11 - 融合升级</h3><br>\n                削弱后的 EF ×1.5，细胞基础倍率 ×25，点数碎片 ×e1e20，复制时间 /2<br><br>花费：3 SP<br><b style=\"color: ",
  "<h3>Bacteria 12 - When will we stop fragmenting</h3><br>\r\n                x1.6 Era Fragments after nerf.<br><br>Cost: 3 SP<br><b style=\"color: ":"<h3>细菌 12 - 我们什么时候才停止碎裂</h3><br>\n                削弱后的纪元碎片 ×1.6。<br><br>花费：3 SP<br><b style=\"color: ",
  "<h3>Bacteria 13 - A new mechanic!</h3><br>\r\n                Unlock the Era Clicker. (v4.2)<br><br>Cost: 10 SP<br><b style=\"color: ":"<h3>细菌 13 - 一项新机制！</h3><br>\n                解锁纪元点击器。（v4.2）<br><br>花费：10 SP<br><b style=\"color: ",
  "<h3>Bacteria 2 - Time-bound</h3><br>\r\n                Record time since Bacteria reset. After 75s, x(Seconds after Bacteria Reset-75)^2 Cell Base Mult, x(1+[Seconds after Bacteria Reset-50]/100) Bacteria Mult, with a cap at 250s and 150s respectively. Also, Cell Softcap scaling is weaker [This effect will not stack if both Bacteria-2 and Bacteria-3 is bought].<br><br>Cost: 1 SP<br><b style=\"color: ":"<h3>细菌 2 - 时间束缚</h3><br>\n                记录自细菌重置以来的时间。75 秒后，细胞基础倍率 ×(细菌重置后秒数-75)^2，细菌 ×(1+[细菌重置后秒数-50]/100)，上限于 250 秒与 150 秒。另外，细胞软上限成长更低 [同时购买细菌 2 与细菌 3 时该效果不叠加]。<br><br>花费：1 SP<br><b style=\"color: ",
  "<h3>Bacteria 3 - Uncap</h3><br>\r\n                Softcap earlier effect of the Cell Massivecap is negated. Also, Cell Softcap Scaling is weaker [This effect will not stack if both Bacteria-2 and Bacteria-3 is bought]. <br><br>Cost: 2 SP<br><b style=\"color: ":"<h3>细菌 3 - 解除上限</h3><br>\n                细胞巨上限的提前软上限效果被取消。另外，细胞软上限成长更低 [同时购买细菌 2 与细菌 3 时该效果不叠加]。<br><br>花费：2 SP<br><b style=\"color: ",
  "<h3>Bacteria 4 - Fragmenting</h3><br>\r\n                x2 Era Fragments after nerf<br><br>Cost: 1 SP<br><b style=\"color: ":"<h3>细菌 4 - 碎裂</h3><br>\n                削弱后的纪元碎片 ×2<br><br>花费：1 SP<br><b style=\"color: ",
  "<h3>Bacteria 5 - Severe Fragmenting</h3><br>\r\n                x3 Era Fragments after nerf. Also, reduce the price of EF Buyable 9 (/5).<br><br>Cost: 2 SP<br><b style=\"color: ":"<h3>细菌 5 - 重度碎裂</h3><br>\n                削弱后的纪元碎片 ×3。另外，EF 可购买项 9 的价格降低（/5）。<br><br>花费：2 SP<br><b style=\"color: ",
  "<h3>Bacteria 6 - Everything.</h3><br>\r\n                Increase Everything Power by 0.002.<br><br>Cost: 1 SP<br><b style=\"color: ":"<h3>细菌 6 - 万物。</h3><br>\n                万物威力提高 0.002。<br><br>花费：1 SP<br><b style=\"color: ",
  "<h3>Bacteria 7 - Effectiveness!</h3><br>\r\n                Get 1 effective Sacrifice Strength.<br><br>Cost: 2 SP<br><b style=\"color: ":"<h3>细菌 7 - 效力！</h3><br>\n                获得 1 点有效献祭强度。<br><br>花费：2 SP<br><b style=\"color: ",
  "<h3>Bacteria 8 - Speedrun</h3><br>\r\n                If you have 0 unspent SP, x1.2 Bacteria. If you have one or more unspent SP, gain a bacteria multiplier based on your fastest bacteria reset. Watch out, if your fastest bacteria reset is over 2mins, then you will receive a nerf. The x1.2 Bacteria mult stays. <br><br>Cost: 1 SP<br>Effect: ":"<h3>细菌 8 - 速通</h3><br>\n                若你有 0 点未花费的 SP，细菌 ×1.2。若你有一点或更多未花费的 SP，则根据你最快的细菌重置获得一个细菌倍率。注意：如果你的最快细菌重置超过 2 分钟，你会受到削弱。×1.2 的细菌倍率依然保留。<br><br>花费：1 SP<br>效果：",
  "<h3>Bacteria 9 - More Upgrades!</h3><br>\r\n                Unlock the first 3 Column 5 Cell Upgrades, and unlock a Era Fragment Upgrade and a Sacrifice Milestone.<br><br>Cost: 2 SP<br><b style=\"color: ":"<h3>细菌 9 - 更多升级！</h3><br>\n                解锁第 5 列的前 3 项细胞升级，并解锁一项纪元碎片升级与一个献祭里程碑。<br><br>花费：2 SP<br><b style=\"color: ",
